import {useState, useCallback, useEffect} from 'react'
import {Banner, FormControl, TextInput} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type {Codespace} from './codespaces-types'

interface RenameCodespaceDialogProps {
  codespace: Codespace | null
  onClose: () => void
  onRenamed: () => void
}

export function RenameCodespaceDialog({codespace, onClose, onRenamed}: RenameCodespaceDialogProps) {
  const [displayName, setDisplayName] = useState('')
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (codespace) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setDisplayName(codespace.displayName ?? '')
      setError(null)
      setSaving(false)
    }
  }, [codespace])

  const handleSave = useCallback(async () => {
    if (!codespace) return
    setSaving(true)
    setError(null)

    try {
      const response = await verifiedFetch(codespace.paths.rename, {
        method: 'PATCH',
        headers: {
          Accept: 'application/json',
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({'codespace[display_name]': displayName}),
      })

      if (!response.ok) {
        throw new Error('Failed to rename codespace')
      }

      onRenamed()
      onClose()
    } catch {
      setError('Failed to rename codespace. Please try again.')
    } finally {
      setSaving(false)
    }
  }, [codespace, displayName, onRenamed, onClose])

  if (!codespace) return null

  return (
    <Dialog
      title="Rename codespace"
      onClose={onClose}
      footerButtons={[
        {content: 'Cancel', onClick: onClose},
        {
          content: saving ? 'Saving...' : 'Save',
          buttonType: 'primary',
          onClick: handleSave,
          disabled: saving || !displayName.trim(),
        },
      ]}
    >
      <Dialog.Body>
        {error && <Banner hideTitle title="Error" variant="critical" description={error} className="mb-2" />}
        <FormControl>
          <FormControl.Label>Display name</FormControl.Label>
          <TextInput value={displayName} onChange={e => setDisplayName(e.target.value)} autoFocus block />
        </FormControl>
      </Dialog.Body>
    </Dialog>
  )
}
