import {Link} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {CodespacesIcon, ArrowRightIcon} from '@primer/octicons-react'
import {MANAGE_CODESPACES_URL} from './codespaces-types'

interface ConcurrencyLimitDialogProps {
  isOpen: boolean
  onClose: () => void
}

export function ConcurrencyLimitDialog({isOpen, onClose}: ConcurrencyLimitDialogProps) {
  if (!isOpen) return null

  return (
    <Dialog title="Maximum running codespaces reached" onClose={onClose}>
      <Dialog.Body>
        <p>You have too many running codespaces. You&apos;ll need to stop some before you start a new codespace.</p>
        <Link
          href={MANAGE_CODESPACES_URL}
          className="d-flex flex-items-center flex-justify-between no-underline tmp-mt-3"
        >
          <span className="d-flex flex-items-center" style={{gap: 'var(--base-size-8)'}}>
            <CodespacesIcon size={16} />
            Manage all codespaces
          </span>
          <ArrowRightIcon size={16} />
        </Link>
      </Dialog.Body>
    </Dialog>
  )
}
