import {Button} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import type {CodespacesHeader} from './codespaces-types'
import type {CodespacesCreateAction} from './use-codespaces-create-action'

export function CodespacesEmptyState({
  header,
  createAction,
}: {
  header: CodespacesHeader
  createAction: CodespacesCreateAction
}) {
  return (
    <Blankslate narrow>
      <Blankslate.Heading>No codespaces</Blankslate.Heading>
      <Blankslate.Description>
        You don&apos;t have any codespaces with this repository checked out
      </Blankslate.Description>
      {header.canCreate &&
        (header.disableOneClickCreation ? (
          <Blankslate.PrimaryAction href={createAction.newWithOptionsUrl}>
            {createAction.label}
          </Blankslate.PrimaryAction>
        ) : (
          <div className="tmp-mt-4 tmp-mb-3">
            <Button onClick={createAction.handleCreate} variant="primary" disabled={createAction.isCreating} labelWrap>
              {createAction.isCreating ? 'Creating codespace...' : createAction.label}
            </Button>
          </div>
        ))}
      <Blankslate.SecondaryAction href={header.helpUrl}>Learn more about codespaces...</Blankslate.SecondaryAction>
    </Blankslate>
  )
}
