import {DeviceDesktopIcon, GlobeIcon, type Icon} from '@primer/octicons-react'
import type {Codespace} from './codespaces-types'

export function getExportLabel(codespace: Codespace): string {
  if (codespace.isUnpublished) return 'Publish to a new repository'
  if (codespace.needsForkToPush) return 'Export changes to a fork'
  return 'Export changes to a branch'
}

export function getEditorIcon(icon: string): Icon {
  return icon === 'globe' ? GlobeIcon : DeviceDesktopIcon
}
