import {useState} from 'react'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {useAnalytics} from '@github-ui/use-analytics'
import type {CodespacesHeader} from './codespaces-types'
import {
  buildCreateFormData,
  GENERIC_CREATE_ERROR,
  readCreateResponse,
  resolveCreateRef,
  withRefQueryParam,
} from './codespace-create-helpers'

const POLL_INTERVAL_MS = 2000
const MAX_POLL_ATTEMPTS = 60

async function pollForVscodeReady(loadingUrl: string): Promise<string> {
  for (let attempt = 0; attempt < MAX_POLL_ATTEMPTS; attempt++) {
    await new Promise(resolve => setTimeout(resolve, POLL_INTERVAL_MS))

    const response = await verifiedFetch(loadingUrl, {
      headers: {Accept: 'text/html'},
    })

    if (response.status === 200) {
      const html = await response.text()
      const match = html.match(/data-codespace-url="([^"]+)"/)
      if (match?.[1]) {
        return match[1]
      }
      break
    }

    if (response.status === 503) {
      throw new Error('Codespace failed to provision')
    }
  }

  throw new Error('Codespace provisioning timed out')
}

function getCreateErrorMessage(error: unknown) {
  if (error instanceof Error && error.message === 'Codespace failed to provision') {
    return error.message
  }

  if (error instanceof Error && error.message === 'Codespace provisioning timed out') {
    return error.message
  }

  return GENERIC_CREATE_ERROR
}

export interface CodespacesCreateAction {
  displayCreateRef?: string
  label: string
  newWithOptionsUrl: string
  isCreating: boolean
  createError: string | null
  showConcurrencyDialog: boolean
  clearCreateError: () => void
  closeConcurrencyDialog: () => void
  handleCreate: () => Promise<void>
}

export function useCodespacesCreateAction(
  header: CodespacesHeader | undefined,
  createRef?: string,
  onCreated?: () => void,
): CodespacesCreateAction {
  const fields = header?.createFormFields
  const resolvedCreateRef = fields ? resolveCreateRef(fields, createRef) : undefined
  const displayCreateRef = createRef
  const label = displayCreateRef ? `Create codespace on ${displayCreateRef}` : 'Create codespace'
  const newWithOptionsUrl = header ? withRefQueryParam(header.newWithOptionsUrl, displayCreateRef) : ''
  const [isCreating, setIsCreating] = useState(false)
  const [createError, setCreateError] = useState<string | null>(null)
  const [showConcurrencyDialog, setShowConcurrencyDialog] = useState(false)
  const {sendAnalyticsEvent} = useAnalytics()

  const fireAnalytics = () => {
    if (!fields) return
    const target = fields.pullRequestId != null ? 'PULL_REQUEST_PAGE_DROPDOWN' : 'REPO_PAGE_DROPDOWN'
    sendAnalyticsEvent('codespace_create.click', target)
  }

  const handleCreate = async () => {
    if (!header || !fields) return

    setIsCreating(true)
    setCreateError(null)
    fireAnalytics()

    if (fields.allowPermissionsUrl) {
      window.open(fields.allowPermissionsUrl, '_blank')
      setIsCreating(false)
      return
    }

    try {
      const response = await verifiedFetch(header.createPath, {
        method: 'POST',
        body: buildCreateFormData(fields, resolvedCreateRef),
        headers: {Accept: 'application/json'},
      })

      if (!response.ok) {
        const body = await readCreateResponse(response)
        if (response.status === 422 && body?.error_type === 'concurrency_limit_error') {
          setShowConcurrencyDialog(true)
          return
        }

        setCreateError(body?.error ?? GENERIC_CREATE_ERROR)
        return
      }

      const json = await readCreateResponse(response)

      if (json?.codespace_url) {
        onCreated?.()
        window.open(json.codespace_url, fields.openInDeeplink ? '_self' : '_blank')
        return
      }

      if (json?.loading_url) {
        const codespaceUrl = await pollForVscodeReady(json.loading_url)
        onCreated?.()
        window.open(codespaceUrl, fields.openInDeeplink ? '_self' : '_blank')
        return
      }

      setCreateError(GENERIC_CREATE_ERROR)
    } catch (error) {
      setCreateError(getCreateErrorMessage(error))
    } finally {
      setIsCreating(false)
    }
  }

  return {
    displayCreateRef,
    label,
    newWithOptionsUrl,
    isCreating,
    createError,
    showConcurrencyDialog,
    clearCreateError: () => setCreateError(null),
    closeConcurrencyDialog: () => setShowConcurrencyDialog(false),
    handleCreate,
  }
}
