import {useCallback} from 'react'
import {ConfirmationDialog} from '@primer/react'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type {Codespace} from './codespaces-types'

interface DeleteCodespaceDialogProps {
  codespace: Codespace | null
  onClose: () => void
  onDeleted: (codespace: Codespace) => void
  onDeleteConfirmed: (codespace: Codespace) => void
  onError: (codespace: Codespace) => void
}

export function DeleteCodespaceDialog({
  codespace,
  onClose,
  onDeleted,
  onDeleteConfirmed,
  onError,
}: DeleteCodespaceDialogProps) {
  const handleClose = useCallback(
    (gesture: 'confirm' | 'cancel' | 'close-button' | 'escape') => {
      if (!codespace) return

      if (gesture === 'confirm') {
        onDeleted(codespace)
        onClose()

        void (async () => {
          try {
            const response = await verifiedFetch(codespace.paths.codespace, {
              method: 'DELETE',
              headers: {Accept: 'application/json'},
            })

            if (!response.ok) {
              onError(codespace)
            } else {
              onDeleteConfirmed(codespace)
            }
          } catch {
            onError(codespace)
          }
        })()
      } else {
        onClose()
      }
    },
    [codespace, onClose, onDeleted, onDeleteConfirmed, onError],
  )

  if (!codespace) return null

  return (
    <ConfirmationDialog
      title="Are you sure?"
      onClose={handleClose}
      confirmButtonContent="Delete"
      confirmButtonType="danger"
    >
      {codespace.deleteConfirmationMessage}
    </ConfirmationDialog>
  )
}
