import {ActionMenu, ActionList, IconButton, Banner} from '@primer/react'
import {useState} from 'react'
import {
  PlusIcon,
  KebabHorizontalIcon,
  ContainerIcon,
  ZapIcon,
  CodespacesIcon,
  QuestionIcon,
  ShareIcon,
} from '@primer/octicons-react'
import type {CodespacesHeader} from './codespaces-types'
import {ShareDeepLinkDialog} from './ShareDeepLinkDialog'
import {CodespacesCreateButton} from './CodespacesCreateButton'
import type {CodespacesCreateAction} from './use-codespaces-create-action'
import {withRefQueryParam} from './codespace-create-helpers'

interface CodespacesHeaderProps {
  header: CodespacesHeader
  createRef?: string
}

export function CodespacesHeaderComponent({
  header,
  createRef,
  createAction,
}: CodespacesHeaderProps & {createAction: CodespacesCreateAction}) {
  const newWithOptionsUrl = withRefQueryParam(header.newWithOptionsUrl, createRef)
  const [showShareDialog, setShowShareDialog] = useState(false)

  return (
    <>
      <div className="color-border-muted border-bottom">
        <div className="tmp-p-3 d-flex flex-items-center flex-justify-between">
          <div>
            <span className="text-bold">Codespaces</span>
            <br />
            <span className="text-small color-fg-subtle">Your workspaces in the cloud</span>
          </div>

          <div className="d-flex flex-items-center" style={{gap: 'var(--base-size-4)'}}>
            <CodespacesCreateButton header={header} createAction={createAction} />
            <ActionMenu>
              <ActionMenu.Anchor>
                <IconButton
                  icon={KebabHorizontalIcon}
                  aria-label="Codespace repository configuration"
                  variant="invisible"
                />
              </ActionMenu.Anchor>
              <ActionMenu.Overlay align="end">
                <ActionList>
                  {header.canCreate && (
                    <ActionList.LinkItem href={newWithOptionsUrl} target="_blank" rel="noopener noreferrer">
                      <ActionList.LeadingVisual>
                        <PlusIcon />
                      </ActionList.LeadingVisual>
                      New with options...
                    </ActionList.LinkItem>
                  )}
                  {header.configureDevContainerUrl && (
                    <ActionList.LinkItem href={header.configureDevContainerUrl}>
                      <ActionList.LeadingVisual>
                        <ContainerIcon />
                      </ActionList.LeadingVisual>
                      Configure dev container
                    </ActionList.LinkItem>
                  )}
                  {header.prebuildsUrl && (
                    <ActionList.LinkItem href={header.prebuildsUrl}>
                      <ActionList.LeadingVisual>
                        <ZapIcon />
                      </ActionList.LeadingVisual>
                      Set up prebuilds
                    </ActionList.LinkItem>
                  )}
                  <ActionList.Divider />
                  <ActionList.LinkItem href={header.manageUrl}>
                    <ActionList.LeadingVisual>
                      <CodespacesIcon />
                    </ActionList.LeadingVisual>
                    Manage codespaces
                  </ActionList.LinkItem>
                  {header.shareUrl && (
                    <ActionList.Item onSelect={() => setShowShareDialog(true)}>
                      <ActionList.LeadingVisual>
                        <ShareIcon />
                      </ActionList.LeadingVisual>
                      Share a deep link
                    </ActionList.Item>
                  )}
                  <ActionList.LinkItem href={header.helpUrl}>
                    <ActionList.LeadingVisual>
                      <QuestionIcon />
                    </ActionList.LeadingVisual>
                    What are codespaces?
                  </ActionList.LinkItem>
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          </div>
        </div>

        {createAction.createError && (
          <Banner
            hideTitle
            title="Create error"
            variant="critical"
            layout="compact"
            description={createAction.createError}
            className="tmp-mx-3 tmp-mb-3"
          />
        )}
      </div>

      {header.shareUrl && (
        <ShareDeepLinkDialog
          isOpen={showShareDialog}
          onClose={() => setShowShareDialog(false)}
          shareUrl={header.shareUrl}
        />
      )}
    </>
  )
}
